//alt:float32 func vjpHardSwishFloat32SIMD(y, x, dOutput, dx []float32) {
func vjpHardSwishFloat64SIMD(y, x, dOutput, dx []float64) { //alt:float64
	//alt:float32 vZero := simd.BroadcastFloat32s(0)
	vZero := simd.BroadcastFloat64s(0) //alt:float64
	//alt:float32 vThree := simd.BroadcastFloat32s(3)
	vThree := simd.BroadcastFloat64s(3) //alt:float64
	//alt:float32 vNegThree := simd.BroadcastFloat32s(-3)
	vNegThree := simd.BroadcastFloat64s(-3) //alt:float64
	//alt:float32 vOneThird := simd.BroadcastFloat32s(1.0 / 3.0)
	vOneThird := simd.BroadcastFloat64s(1.0 / 3.0) //alt:float64
	//alt:float32 vHalf := simd.BroadcastFloat32s(0.5)
	vHalf := simd.BroadcastFloat64s(0.5) //alt:float64
	vLen := vZero.Len()
	i := 0
	for ; i+vLen <= len(dOutput); i += vLen {
		//alt:float32 vX := simd.LoadFloat32s(x[i:])
		vX := simd.LoadFloat64s(x[i:]) //alt:float64
		//alt:float32 vDOut := simd.LoadFloat32s(dOutput[i:])
		vDOut := simd.LoadFloat64s(dOutput[i:]) //alt:float64
		mid := vDOut.Mul(vX.MulAdd(vOneThird, vHalf))
		res := mid.IfElse(vX.Greater(vNegThree), vZero)
		res = vDOut.IfElse(vX.GreaterEqual(vThree), res)
		res.Store(dx[i:])
	}
	if i < len(dOutput) {
		//alt:float32 vX, _ := simd.LoadFloat32sPart(x[i:])
		vX, _ := simd.LoadFloat64sPart(x[i:]) //alt:float64
		//alt:float32 vDOut, _ := simd.LoadFloat32sPart(dOutput[i:])
		vDOut, _ := simd.LoadFloat64sPart(dOutput[i:]) //alt:float64
		mid := vDOut.Mul(vX.MulAdd(vOneThird, vHalf))
		res := mid.IfElse(vX.Greater(vNegThree), vZero)
		res = vDOut.IfElse(vX.GreaterEqual(vThree), res)
		res.StorePart(dx[i:])
	}
}

